    "full": "Each time a model from your army with the Oath of Moment ability makes an attack that targets your Oath of Moment target, you can re‑roll a Wound roll of 1. Each time a model in a Darnath Lysander unit from your army makes an attack that targets your Oath of Moment target, you can re‑roll the Wound roll.",
